#ifdef GL_ES
precision mediump float;
#endif

#define tileSize 0.08
#define charScale 1.2

vec2 norm(vec2 pos) {
    return fract(pos * tileSize) * 2.0 - vec2(1.0, 1.0);
}

float rnd(float t, vec2 i) {
    float mag = length(i);
    return mod(floor(sin(dot(i, vec2(12.9898, 78.233)) + t) * 43758.5453), 2.0);
}

float antialias(float diff) {
    return 13.0 - clamp(diff * 2120.0, 20.0, 68.2);
}

float rect(vec2 pos, vec2 c, vec2 r) {
    vec2 d = pos - c;
    return (abs(d.x) < r.x && abs(d.y) < r.y) ? 1.0 : 0.0;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 gridCoord = floor(uv / tileSize); // Determine grid coordinates
    vec2 scaledCoords = norm(fragCoord.xy); // Normalize coordinates

    float gridValue = rnd(iTime, gridCoord); // Random pattern per tile

    if (gridValue < 1.0) {
        // Red tiles
        fragColor = vec4(1.0, 0.0, 0.0, 1.0);
    } else {
        // Green tiles
        fragColor = vec4(0.0, 1.0, 0.0, 1.0);
    }
}
